async function loadDb(){await mkdir(DATA_DIR,{recursive:true});if(!existsSync(DATA_FILE)){await writeFile(DATA_FILE,JSON.stringify(emptyDb,null,2));return structuredClone(emptyDb)}try{return {...emptyDb,...JSON.parse(await readFile(DATA_FILE,'utf8'))}}catch{return structuredClone(emptyDb)}}
let db=await loadDb(); let saveTimer;
function saveSoon(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>writeFile(DATA_FILE,JSON.stringify(db,null,2)),100)}
async function saveNow(){clearTimeout(saveTimer);await writeFile(DATA_FILE,JSON.stringify(db,null,2))}
function id(p){return p+'_'+Date.now().toString(36)+'_'+crypto.randomBytes(4).toString('hex')}
function json(res,status,obj){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store'});res.end(JSON.stringify(obj))}
function body(req){return new Promise((resolve,reject)=>{let s='';req.on('data',c=>{s+=c;if(s.length>2e6){reject(new Error('body_too_large'));req.destroy()}});req.on('end',()=>{try{resolve(s?JSON.parse(s):{})}catch(e){reject(e)}});req.on('error',reject)})}
function ensureUser(uid,profile={}){if(!db.users[uid])db.users[uid]={id:uid,firstName:profile.first_name||'',username:profile.username||'',reminder:{enabled:true,mode:'weekly',weekday:0,time:'19:00',monthlyDay:1},createdAt:new Date().toISOString()};return db.users[uid]}
function validateTelegramInitData(initData){
  if(!BOT_TOKEN||!initData)return null;
  const p=new URLSearchParams(initData); const hash=p.get('hash'); if(!hash||!/^[a-f0-9]{64}$/i.test(hash))return null; p.delete('hash');
  const dataCheck=[...p.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`${k}=${v}`).join('\n');
  const secret=crypto.createHmac('sha256','WebAppData').update(BOT_TOKEN).digest();
  const expected=crypto.createHmac('sha256',secret).update(dataCheck).digest('hex');
  if(!crypto.timingSafeEqual(Buffer.from(hash,'hex'),Buffer.from(expected,'hex')))return null;
  const authDate=Number(p.get('auth_date')); if(!authDate||Math.abs(Date.now()/1000-authDate)>86400)return null;
  try{return JSON.parse(p.get('user')||'null')}catch{return null}
}
function getUid(req){const tg=validateTelegramInitData(req.headers['x-telegram-init-data']||'');if(tg?.id)return String(tg.id);if(process.env.NODE_ENV!=='production')return req.headers['x-demo-user']||'demo-user';return null}
function normalizeOil(x={}){if(typeof x==='string')return {brand:'',name:x,viscosity:x,volume:''};return {brand:String(x.brand||'').slice(0,80),name:String(x.name||'').slice(0,120),viscosity:String(x.viscosity||'').slice(0,30),volume:String(x.volume||'').slice(0,30)}}
function normalizeCar(x){const n=Number(x.odometer),interval=Number(x.serviceIntervalKm);const oil=normalizeOil(x.oil&&typeof x.oil==='object'?x.oil:{brand:x.oilBrand,name:x.oilName,viscosity:x.oilViscosity||x.oil,volume:x.oilVolume});const mr=x.mileageReminder||{};return {...x,id:x.id||id('car'),stsNumber:String(x.stsNumber||''),name:String(x.name||`${x.make||''} ${x.model||''}`).trim()||'Мой автомобиль',make:String(x.make||''),model:String(x.model||''),year:Number.isFinite(Number(x.year))?Number(x.year):null,color:String(x.color||''),plate:String(x.plate||''),vin:String(x.vin||''),odometer:Number.isFinite(n)&&n>=0?n:0,serviceIntervalKm:Number.isFinite(interval)&&interval>0?interval:10000,lastServiceOdometer:Number.isFinite(Number(x.lastServiceOdometer))?Number(x.lastServiceOdometer):Number.isFinite(n)&&n>=0?n:0,nextServiceDate:/^\d{4}-\d{2}-\d{2}$/.test(x.nextServiceDate||'')?x.nextServiceDate:null,lastServiceDate:/^\d{4}-\d{2}-\d{2}$/.test(x.lastServiceDate||'')?x.lastServiceDate:null,reminderKm:Number.isFinite(Number(x.reminderKm))?Math.max(0,Number(x.reminderKm)):1000,reminderDays:Number.isFinite(Number(x.reminderDays))?Math.max(0,Number(x.reminderDays)):0,oil,oilVolume:oil.volume,mileageReminder:{enabled:mr.enabled!==false,mode:['interval','monthly'].includes(mr.mode)?mr.mode:'interval',intervalDays:Math.min(30,Math.max(1,Number(mr.intervalDays)||7)),monthlyDay:Math.min(31,Math.max(1,Number(mr.monthlyDay)||1)),lastAskedAt:mr.lastAskedAt||null},createdAt:x.createdAt||new Date().toISOString()}}
function due(car,now=new Date()){const km=Math.max(0,car.serviceIntervalKm-(car.odometer-car.lastServiceOdometer));const date=car.nextServiceDate?Math.ceil((new Date(`${car.nextServiceDate}T23:59:59`)-now)/86400000):null;return{kmRemaining:km,dateRemaining:date,dueByKm:km<=0,dueByDate:date!==null&&date<=0,due:km<=0||(date!==null&&date<=0)}}
function safeCar(c){return {...c,due:due(c)}}
