async function refreshKnowledge(){if(!KNOWLEDGE_UPDATE_URL)return {updated:false,reason:'not_configured'};try{const r=await fetch(KNOWLEDGE_UPDATE_URL,{headers:{accept:'application/json'},signal:AbortSignal.timeout(8000)});if(!r.ok)throw new Error(`http_${r.status}`);const data=await r.json();const rows=Array.isArray(data)?data:(Array.isArray(data.rules)?data.rules:[]);let added=0;for(const x of rows){if(!x||!x.make||!x.model||!Number.isFinite(Number(x.mileage)))continue;const rule={make:String(x.make),model:String(x.model),minYear:Number(x.minYear)||0,maxYear:Number(x.maxYear)||9999,mileage:Number(x.mileage),title:String(x.title||'Профилактическая проверка').slice(0,160),description:String(x.description||'Проверить узел по регламенту производителя.').slice(0,600),category:String(x.category||'general').slice(0,60),source:String(x.source||'remote knowledge feed').slice(0,200)};const exists=VEHICLE_KNOWLEDGE.some(z=>z.make===rule.make&&z.model===rule.model&&z.mileage===rule.mileage&&z.title===rule.title&&z.minYear===rule.minYear&&z.maxYear===rule.maxYear);if(!exists){VEHICLE_KNOWLEDGE.push(rule);added++}}return {updated:true,added,total:VEHICLE_KNOWLEDGE.length}}catch(e){console.error('knowledge refresh failed',e.message);return {updated:false,error:e.message}}}
function suspiciousMileage(car,value){const current=Number(car?.odometer||0),v=Number(value);if(!current||!Number.isFinite(v))return null;const delta=v-current;const pct=current?delta/current:0;const suspicious=delta>10000&&pct>0.12;return suspicious?{current,entered:v,delta,percent:Math.round(pct*100)}:null}
function recordMileage(uid,car,value,source='manual'){const v=Number(value);if(!Number.isFinite(v)||v<0)return null;const day=new Date().toISOString();const k=id('mile');const rec={id:k,userId:uid,carId:car.id,odometer:v,recordedAt:day,source};db.mileageHistory[k]=rec;return rec}
function validWebhook(req){return !WEBHOOK_SECRET||req.headers['x-telegram-bot-api-secret-token']===WEBHOOK_SECRET}
async function telegram(method,payload){if(!BOT_TOKEN)throw new Error('telegram_token_missing');const r=await fetch(`https://api.telegram.org/bot${BOT_TOKEN}/${method}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.description||`telegram_${method}_failed`);return d.result}
async function handleUpdate(u){const msg=u?.message;if(!msg?.chat?.id)return;const uid=String(msg.chat.id);const user=ensureUser(uid,msg.from||{});const text=String(msg.text||'').trim();
  if(text==='/start'||text==='/help'){await telegram('sendMessage',{chat_id:uid,text:'🚗 АвтоПлан\n\nОткройте приложение, чтобы добавить автомобиль, настроить ТО и напоминания.',reply_markup:{inline_keyboard:[[ {text:'🚗 Открыть АвтоПлан',web_app:{url:process.env.MINI_APP_URL||'https://example.com'}} ]]}});return}
  if(db.pendingMileage[uid]){const car=db.cars[db.pendingMileage[uid].carId];const value=Number(text.replace(/[^0-9.]/g,''));if(car&&car.userId===uid&&Number.isFinite(value)&&value>=car.odometer){car.odometer=value;recordMileage(uid,car,value,'telegram');delete db.pendingMileage[uid];saveSoon();await telegram('sendMessage',{chat_id:uid,text:`✅ Пробег сохранён: ${value.toLocaleString('ru-RU')} км`});return}}
  if(/^\d+[,.]?\d*$/.test(text)){await telegram('sendMessage',{chat_id:uid,text:'Если приложение попросило обновить пробег, отправьте число ещё раз. Для управления автомобилем откройте Mini App.'});return}
  ensureUser(uid,user); saveSoon();
}

