function stationDistance(lat1,lon1,lat2,lon2){const R=6371;const p=Math.PI/180;const a=0.5-Math.cos((lat2-lat1)*p)/2+Math.cos(lat1*p)*Math.cos(lat2*p)*(1-Math.cos((lon2-lon1)*p))/2;return R*2*Math.asin(Math.sqrt(a))}
async function searchStations(text,lat,lon){
 const key=process.env.YANDEX_SEARCH_API_KEY;
 if(!key)return {provider:'none',stations:[]};
 const qs=new URLSearchParams({apikey:key,text:text||'автосервис',type:'biz',lang:'ru_RU',results:'20'});
 if(Number.isFinite(lat)&&Number.isFinite(lon)){qs.set('ll',`${lon},${lat}`);qs.set('spn','0.25,0.25');qs.set('rspn','1')}
 const r=await fetch(`https://search-maps.yandex.ru/v1/?${qs}`); if(!r.ok)throw new Error('station_search_failed'); const d=await r.json();
 const features=Array.isArray(d.features)?d.features:[];
 return {provider:'yandex',stations:features.map(f=>{const c=f.geometry?.coordinates||[];const p=f.properties||{};const meta=p.CompanyMetaData||{};const name=meta.name||p.name||'СТО';const addr=meta.address||p.description||'';const phone=(meta.Phones||[])[0]?.formatted||'';const hours=(meta.Hours?.text)||'';const coords=Array.isArray(c)&&c.length===2?{lat:c[1],lon:c[0]}:null;const distance=coords&&Number.isFinite(lat)&&Number.isFinite(lon)?stationDistance(lat,lon,coords.lat,coords.lon):null;const local=Object.values(db.stations).find(x=>x.externalId===String(meta.id||'')); const ss=stationSummary(String(meta.id||'')); return {id:meta.id||id('ext'),name,address:addr,phone,hours,coords,distance,sponsored:!!local?.sponsored,source:'yandex',rating:ss.rating,reviews:ss.reviews};}).sort((a,b)=>(a.distance??9999)-(b.distance??9999))};
}
